import { repos } from '../core/repositories.js';
import { state } from '../core/state.js';
import { esc, humanError, dateFmt, money } from '../core/utils.js';
import { pageHeader, setMainHtml, openForm, toast, setError, empty, badge } from '../ui/components.js';
import { t } from '../i18n/index.js';

let servicesCache=null;
async function services(){if(servicesCache)return servicesCache;const r=await fetch('./assets/catalogs/consulting-services.json?v=20150',{cache:'no-cache'});if(!r.ok)throw new Error(`CONSULTING_CATALOG_${r.status}`);servicesCache=await r.json();return servicesCache;}
const statusTone=s=>['delivered','closed','paid'].includes(s)?'ok':['cancelled','failed'].includes(s)?'danger':['quoted','accepted','in_review'].includes(s)?'warn':'neutral';
function requestCard(r){return `<article class="kx-consult-request"><header><div><span>${esc(r.consultation_type||'')}</span><strong>${esc(r.summary||'')}</strong></div>${badge(r.status||'requested',statusTone(r.status))}</header><p>${esc([r.territory,r.municipality,r.discipline].filter(Boolean).join(' · '))}</p><small>${dateFmt(r.created_at)}</small>${r.quote_amount_minor!=null?`<div class="kx-consult-quote"><b>${money(Number(r.quote_amount_minor)/100,r.quote_currency||'EUR')}</b><span>${esc(r.quote_note||t('prepilot.quoteOnly'))}</span>${r.status==='quoted'?`<button class="btn btn-primary btn-sm" data-kx-consult-accept="${esc(r.id)}">${esc(t('prepilot.acceptedQuote'))}</button>`:''}</div>`:`<div class="kx-consult-quote is-pending"><b>${esc(t('prepilot.noPrice'))}</b></div>`}<footer><span>${esc(t('prepilot.documents'))}: ${(r.documents||[]).length}</span><label class="btn btn-ghost btn-sm">${esc(t('prepilot.upload'))}<input type="file" hidden data-kx-consult-file="${esc(r.id)}" accept="application/pdf,image/jpeg,image/png,image/webp"></label></footer></article>`;}
function contextPayload(){const s=state.session||{};return s.club_id?{subject_type:'club',subject_id:s.club_id,entity_type:'club'}:{};}
export async function renderConsulting({container=null}={}){
  const setContent=markup=>container?container.innerHTML=markup:setMainHtml(markup);
  setContent(`<div class="loading-card">${esc(t('common.states.loading'))}</div>`);
  try{const [catalog,rows]=await Promise.all([services(),repos.consulting.mine().catch(()=>[])]);const list=Array.isArray(rows)?rows:[];
    setContent(`<section class="kx-resource-hero is-consulting" style="--kx-resource-hero:url('./assets/brand-heroes/hero-consulting.webp')"><div class="kx-resource-hero-copy"><span>KOMBAX</span><h1>${esc(t('prepilot.consultingTitle'))}</h1><p>${esc(t('prepilot.consultingLead'))}</p><button class="btn btn-primary" id="kx-consult-new">${esc(t('prepilot.request'))}</button></div></section><section class="kx-consult-services">${catalog.services.map(s=>`<article><span>${esc(t('prepilot.quoteOnly'))}</span><h3>${esc(s.title)}</h3><p>${esc(s.scope)}</p><small>${esc((s.deliverables||[]).join(' · '))}</small></article>`).join('')}</section><h2 class="section-title">${esc(t('prepilot.myRequests'))}</h2><div class="kx-consult-requests">${list.length?list.map(requestCard).join(''):empty(t('prepilot.noRequests'))}</div>`);
    document.getElementById('kx-consult-new')?.addEventListener('click',()=>openForm({title:t('prepilot.request'),subtitle:t('prepilot.consultingLead'),width:'760px',fields:[{name:'consultation_type',label:t('prepilot.service'),type:'select',required:true,options:catalog.services.map(s=>({value:s.service_code,label:s.title}))},{name:'summary',label:t('prepilot.summary'),type:'textarea',rows:5,required:true,full:true},{name:'territory',label:t('prepilot.territory')},{name:'municipality',label:t('prepilot.municipality')},{name:'discipline',label:t('prepilot.discipline')},{name:'target_date',label:t('prepilot.targetDate'),type:'date'},{name:'minors_involved',label:t('prepilot.minors'),type:'checkbox',full:true},{name:'foreign_athletes',label:t('prepilot.foreign'),type:'checkbox',full:true},{name:'ticket_sales',label:t('prepilot.ticketSales'),type:'checkbox',full:true},{name:'venue_defined',label:t('prepilot.venueDefined'),type:'checkbox',full:true}],submitText:t('prepilot.submit'),onSubmit:async v=>{await repos.consulting.create({...contextPayload(),...v});toast(t('prepilot.requestCreated'));await renderConsulting({container});}}));
    document.querySelectorAll('[data-kx-consult-file]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;input.disabled=true;try{await repos.consulting.uploadDocument(input.dataset.kxConsultFile,file);toast(t('prepilot.upload'));await renderConsulting({container});}catch(error){setError(error);input.disabled=false;}}));
    document.querySelectorAll('[data-kx-consult-accept]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await repos.consulting.acceptQuote(b.dataset.kxConsultAccept);toast(t('prepilot.paymentPending'));await renderConsulting({container});}catch(error){setError(error);b.disabled=false;}}));
  }catch(error){setError(error);setContent(`${pageHeader(t('prepilot.consultingTitle'))}<div class="empty-card"><strong>${esc(t('errors.genericTitle'))}</strong><p>${esc(humanError(error)||'CONSULTING_ERROR')}</p></div>`);}
}
